Here's a sample C++ program that reads a text file line by line, counts the number of occurrences of a specific word (user-defined), and outputs the count:

```cpp
#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>

int main() {
    // User-defined variables
    std::string fileName;
    std::string wordToCount;
    int count = 0;

    // Prompt user for file name and word to count
    std::cout << "Enter the name of the text file: ";
    std::getline(std::cin, fileName);

    std::cout << "Enter the word to count: ";
    std::getline(std::cin, wordToCount);

    // Open the file for reading
    std::ifstream inputFile(fileName);

    if (!inputFile) {
        std::cerr << "Error opening file: " << fileName << std::endl;
        return 1;
    }

    // Read the file line by line
    std::string line;
    while (getline(inputFile, line)) {
        // Convert line to lowercase (optional)
        std::transform(line.begin(), line.end(), line.begin(), ::tolower);

        // Count occurrences of the word in the line
        size_t pos = 0;
        while ((pos = line.find(wordToCount, pos)) != std::string::npos) {
            count++;
            pos += wordToCount.length(); // Move pos to next occurrence
        }
    }

    // Close the file
    inputFile.close();

    // Output the count
    std::cout << "The word \"" << wordToCount << "\" appears " << count << " times in " << fileName << "." << std::endl;

    return 0;
}
```

Note: This program assumes that the file exists and is readable. It also converts all text in the file to lowercase (optional) before searching for the word to count, to make the search case-insensitive. If you want to make the search case-sensitive, simply remove the `std::transform()` function call.
